INSERT INTO thread_turns (id, thread_id, question, answer, uncertainty, outcome, result_json, created_at) VALUES ('turn_mwc9vsg0', 'th_w1tsv0lhmwc9vsfq', 'How do adversaries achieve persistence through Windows scheduled tasks?', 'Adversaries frequently leverage the Windows Task Scheduler (MITRE ATT&CK T1053.005) to execute malicious binaries or scripts at system startup or on scheduled recurring intervals. By registering tasks under elevated privileges such as SYSTEM or LocalService via schtasks.exe or Register-ScheduledTask, attackers establish resilient persistence that survives system reboots and administrative session logoffs.', NULL, 'ok', '{"meta": {"generated_at": "2026-11-11T15:27:18.710Z", "retrieval_version": "2026.3.1"}, "query": "How do adversaries achieve persistence through Windows scheduled tasks?", "answer": "Adversaries frequently leverage the Windows Task Scheduler (MITRE ATT&CK T1053.005) to execute malicious binaries or scripts at system startup or on scheduled recurring intervals. By registering tasks under elevated privileges such as SYSTEM or LocalService via schtasks.exe or Register-ScheduledTask, attackers establish resilient persistence that survives system reboots and administrative session logoffs.", "status": "ok", "outcome": "ok", "refusal": null, "results": [{"lab": {"lab_id": "lab_t1053_win", "lab_type": "interactive_vm", "platform": "windows", "available": true, "objective": "Observe Windows Event Logs when creating persistence tasks", "difficulty": "Intermediate", "launchable": true, "network_mode": "airgapped", "technique_id": "T1053.005", "session_steps": ["Log in to target Windows Server VM", "Run benign schtasks simulation script", "Inspect Event Viewer Security log for Event 4698 (A scheduled task was created)"], "technique_name": "Scheduled Task Persistence Lab", "safety_boundary": "Strict sandbox egress filtering", "validation_source": "MITRE Enterprise", "estimated_duration": "15 min", "scenario_objective": "Detect unauthori