INSERT INTO thread_turns (id, thread_id, question, answer, uncertainty, outcome, result_json, created_at) VALUES ('turn_8c9df021a878', 'th_a469451b0e82', 'ransomware encryption T1486', '**Analysis of Data Encrypted for Impact (Ransomware) (T1486)**:
