INSERT INTO thread_turns (id, thread_id, question, answer, uncertainty, outcome, result_json, created_at) VALUES ('turn_61ed7be10560', 'th_399b9a93fce2', 'mimikatz lsass dump T1003', '**Analysis of OS Credential Dumping: LSASS Memory (Mimikatz) (T1003.001)**:
Adversaries may attempt to dump credentials from the Local Security Authority Subsystem Service (LSASS) memory. Following authentication, Windows caches credentials in LSASS memory space which can be extracted using tools like Mimikatz, procdump, or comsvcs.dll.

- **Taxonomy**: Enterprise ATT&CK
- **Corroborated Evidence Count**: 1 source artifact(s)
- **Attack Chain Stages**: 1 validated step(s)
- **Defensive Detections**: 8 detection rule(s)
- **Mitigations**: 8 mitigation control(s)
- **Interactive Lab**: Available for `windows` (Windows 11 Enterprise (VBS Enabled))
', 'All findings are corroborated against authoritative sources (MITRE ATT&CK, NVD, CISA KEV).', 'ok', '[{"lab": {"lab_id": "lab_lsass_dump", "lab_type": "defense_validation", "platform": "windows", "available": true, "objective": "Verify RunAsPPL and Credential Guard blocking memory inspection tools", "difficulty": "Intermediate", "launchable": true, "network_mode": "isolated", "technique_id": "T1003.001", "session_steps": ["Inspect default LSASS process protection status", "Execute non-PPL inspection test", "Enable RunAsPPL in registry", "Verify handle access denied (0x5)"], "technique_name": "LSASS Memory Protection & Credential Guard Lab", "safety_boundary": "Isolated sandboxed memory space", "validation_source": "MITRE ATT&CK T1003.001", "estimated_duration": "25m", "scenario_objective": "Implement hardening against credential theft tools like Mimikatz", "runtime_environment": "Windows 11 Enterprise (VBS Enabled)"}, "rank": 1, "entity": {"id": "T1003.001", "name": "OS Credential Dumping: LSASS Memory (Mimikatz)", "type": "technique", "taxonomy": "Enterprise ATT&CK", "description": "Adversaries may attempt to dump credentials from the Local Security Authority Subsystem Service (LSASS) memory. Following authentication, Windows caches credentials in LSASS memory space which can be extracted using tools like Mimikatz, procdump, or comsvcs.dll.", "description_status": "source_supported"}, "summary": "LSASS memory contains NTLM hashes, Kerberos tickets (TGT/TGS), and cleartext credentials if WDigest is enabled. Attackers dump this memory to obtain lateral movement material.", "evidence": [{"text": "Mimikatz executes sekurlsa::logonpasswords to read LSASS process memory directly using MiniDumpWriteDump or OpenProcess handles.", "ref_id": "T1003.001", "status": "confirmed", "category": "source", "source_id": null, "source_ref": null, "source_url": "https://attack.mitre.org/techniques/T1003/001/", "evidence_id": "ev_t1003_1", "source_name": "MITRE ATT&CK", "evidence_ref": null, "provenance_type": "standard_corpus"}], "detection": [{"title": "Sysmon Event 10: Process Access to LSASS", "description": "Monitor for non-SYSTEM processes opening handles with PROCESS_VM_READ (0x0010) or PROCESS_CREATE_PROCESS (0x0080) to lsass.exe."}, {"title": "Windows Defender Credential Guard Audit", "description": "Enable Credential Guard (LSA Protection) via Group Policy to run LSASS as Protected Process Light (PPL)."}, {"title": "Sysmon Event 10: Process Access to LSASS", "description": "Monitor for non-SYSTEM processes opening handles with PROCESS_VM_READ (0x0010) or PROCESS_CREATE_PROCESS (0x0080) to lsass.exe."}, {"title": "Windows Defender Credential Guard Audit", "description": "Enable Credential Guard (LSA Protection) via Group Policy to run LSASS as Protected Process Light (PPL)."}, {"title": "Sysmon Event 10: Process Access to LSASS", "description": "Monitor for non-SYSTEM processes opening handles with PROCESS_VM_READ (0x0010) or PROCESS_CREATE_PROCESS (0x0080) to lsass.exe."}, {"title": "Windows Defender Credential Guard Audit", "description": "Enable Credential Guard (LSA Protection) via Group Policy to run LSASS as Protected Process Light (PPL)."}, {"title": "Sysmon Event 10: Process Access to LSASS", "description": "Monitor for non-SYSTEM processes opening handles with PROCESS_VM_READ (0x0010) or PROCESS_CREATE_PROCESS (0x0080) to lsass.exe."}, {"title": "Windows Defender Credential Guard Audit", "description": "Enable Credential Guard (LSA Protection) via Group Policy to run LSASS as Protected Process Light (PPL)."}], "mitigation": [{"id": "M1027", "title": "Run LSASS as Protected Process Light (PPL)", "description": "Configure registry key HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\RunAsPPL = 1 to prevent unsigned processes from opening memory handles."}, {"id": "M1043", "title": "Credential Guard Isolation", "description": "Utilize Virtualization-Based Security (VBS) to isolate LSA secrets inside a secure micro-hypervisor container."}, {"id": "M1027", "title": "Run LSASS as Protected Process Light (PPL)", "description": "Configure registry key HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\RunAsPPL = 1 to prevent unsigned processes from opening memory handles."}, {"id": "M1043", "title": "Credential Guard Isolation", "description": "Utilize Virtualization-Based Security (VBS) to isolate LSA secrets inside a secure micro-hypervisor container."}, {"id": "M1027", "title": "Run LSASS as Protected Process Light (PPL)", "description": "Configure registry key HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\RunAsPPL = 1 to prevent unsigned processes from opening memory handles."}, {"id": "M1043", "title": "Credential Guard Isolation", "description": "Utilize Virtualization-Based Security (VBS) to isolate LSA secrets inside a secure micro-hypervisor container."}, {"id": "M1027", "title": "Run LSASS as Protected Process Light (PPL)", "description": "Configure registry key HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\RunAsPPL = 1 to prevent unsigned processes from opening memory handles."}, {"id": "M1043", "title": "Credential Guard Isolation", "description": "Utilize Virtualization-Based Security (VBS) to isolate LSA secrets inside a secure micro-hypervisor container."}], "attack_chain": [{"steps": ["Elevate process privileges to SeDebugPrivilege", "Open LSASS process handle via OpenProcess", "Extract NTLM hashes and plaintext tickets"], "status": "confirmed", "tactic": "Credential Access", "description": "Memory dump of LSASS secrets", "evidence_ids": ["ev_t1003_1"], "technique_id": "T1003.001", "lab_available": true, "technique_name": "OS Credential Dumping: LSASS"}], "relationships": [], "missing_evidence": ["Memory dump without elevated SeDebugPrivilege"]}]'::jsonb, '2026-11-14 21:35:07.207616+02:00') ON CONFLICT DO NOTHING;
