', 'All findings are corroborated against authoritative sources (MITRE ATT&CK, NVD, CISA KEV).', 'ok', '[{"lab": {"lab_id": "lab_t1053_win", "lab_type": "interactive_vm", "platform": "windows", "available": true, "objective": "Observe Windows Event Logs when creating persistence tasks", "difficulty": "Intermediate", "launchable": true, "network_mode": "airgapped", "technique_id": "T1053.005", "session_steps": ["Log in to target Windows Server VM", "Run benign schtasks simulation script", "Inspect Event Viewer Security log for Event 4698 (A scheduled task was created)"], "technique_name": "Scheduled Task Persistence Lab", "safety_boundary": "Strict sandbox egress filtering", "validation_source": "MITRE Enterprise", "estimated_duration": "15 min", "scenario_objective": "Detect unauthorized task creation", "runtime_environment": "Isolated Sandbox Hypervisor"}, "rank": 1, "entity": {"id": "T1053.005", "name": "Scheduled Task", "type": "technique", "taxonomy": "Enterprise ATT&CK", "description": "Adversaries may abuse the Windows Task Scheduler to facilitate initial or recurring execution of malicious code.", "description_status": "source_supported"}, "summary": "Persistence via Task Scheduler remains a premier technique across commodity and APT groups due to native OS integration.", "evidence": [{"text": "Task Scheduler can be abused using schtasks.exe or Register-ScheduledTask PowerShell cmdlet to trigger tasks as SYSTEM or high-privilege users.", "ref_id": "T1053.005", "status": "confirmed", "category": "source", "source_id": "src_mitre_t1053", "source_ref": "ATT&CK v14", "source_url": "https://attack.mitre.org/techniques/T1053/005/", "evidence_id": "ev_01", "source_name": "MITRE ATT&CK", "evidence_ref": "T1053.005#detection", "provenance_type": "standard_corpus"}], "detection": [{"title": "Process Monitoring for schtasks.exe", "description": "Audit Command Line executions containing /create flags and suspicious /tr parameters (Event ID 4688)."}, {"title": "Task Scheduler Event Logs", "description": "Monitor Microsoft-Windows-TaskScheduler/Operational for Event 106 (Task scheduled) and Event 140 (Task updated)."}], "mitigation": [{"id": "M1047", "title": "Audit Tasks and Restrict Access", "description": "Configure Group Policy to prevent non-administrative users from scheduling jobs."}, {"id": "M1028", "title": "Operating System Configuration", "description": "Enable PowerShell Constrained Language Mode and Script Block Logging (Event 4104)."}], "attack_chain": [{"steps": ["Identify target persistence path in Task Scheduler registry hive", "Execute schtasks /create /tn ''SecurityUpdate'' /tr ''c:\\temp\\update.exe'' /sc onlogon", "Verify execution upon user logon"], "status": "confirmed", "tactic": "Persistence", "description": "Task created under \\Microsoft\\Windows\\Maintenance with elevated triggers.", "evidence_ids": ["ev_01"], "technique_id": "T1053.005", "lab_available": true, "technique_name": "Scheduled Task"}], "relationships": [{"to_id": "T1053", "from_id": "T1053.005", "relation_type": "subtechnique-of", "provenance_type": "mitre_taxonomy", "relationship_id": "rel_01"}], "missing_evidence": []}, {"lab": null, "rank": 2, "entity": {"id": "APT3", "name": "APT3 (Gothic Panda)", "type": "threat_actor", "taxonomy": "MITRE ATT&CK Groups", "description": "China-nexus threat group active since ~2010 known for spearphishing campaigns and browser exploitation.", "description_status": "source_supported"}, "summary": "APT3 has executed operations targeting aerospace, defense, and high-tech firms utilizing phased initial access and living-off-the-land interpreters.", "evidence": [{"text": "APT3 has sent spearphishing emails containing a link that downloads malicious files and malicious attachments to gain initial network access.", "ref_id": "T1566", "status": "confirmed", "category": "source", "source_id": "src_mitre_g0022", "source_ref": "Group G0022", "source_url": "https://attack.mitre.org/groups/G0022/", "evidence_id": "ev_ap